INSERT INTO monster VALUES (607,'Yeth Hound','Yeth Hound',NULL,'Medium','Outsider','Extraplanar, Evil','3d8+6 (19 hp)','+6','40 ft. (8 squares), fly 60 ft. (good)','20 (+2 Dex, +8 natural), touch 12, flat-footed 18','+3','+6','Bite +6 melee (1d8+4)','Bite +6 melee (1d8+4)','5 ft.','5 ft.','Bay, trip','Damage reduction 10/silver, darkvision 60 ft., flight, scent','Fort +5, Ref +5, Will +5','Str 17, Dex 15, Con 15, Int 6, Wis 14, Cha 10','Listen +11, Spot +11, Search +7, Survival +11 (+13 following tracks)*',NULL,'Improved Initiative, Track',NULL,'An evil-aligned plane','Solitary, pair, or pack (6-11)','3','None','Always neutral evil','4-6 HD (Medium); 7-9 HD (Large)','+3 (cohort)','Bay (Su), Flight (Su), Trip (Ex)','Yeth hound; CR 3; Medium outsider (extraplanar, evil); HD 3d8+6; hp 19; Init +6; Spd 40 ft. (8 squares), fly 60 ft. (good); AC 20 (+2 dex, +8 natural), touch 12, flat-footed 18; Base Atk +3; Grp +6; Atk +6 melee (1d8+4, bite); Full Atk +6 melee (1d8+4, bite); Space/Reach 5 ft./5 ft.; SA Bay, trip; SQ Damage reduction 10/silver, darkvision 60 ft., flight, scent; AL NE; SV Fort +5, Ref +5, Will +5; Str 17, Dex 15, Con 15, Int 6, Wis 14, Cha 10\n\nSkills and Feats: Listen +11, Spot +11, Search +7, Survival +11 (+13 following tracks)*; Improved Initiative, Track','\n      <div topic=\"Yeth Hound\" level=\"2\"><p><h2>Yeth Hound</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Yeth Hound</b><br/></td>\n\n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Medium Outsider (Extraplanar, Evil)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>3d8+6 (19 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>40 ft. (8 squares), fly 60 ft. (good)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>20 (+2 Dex, +8 natural), touch 12, flat-footed 18<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+3/+6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Bite +6 melee (1d8+4)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Bite +6 melee (1d8+4)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>5 ft./5 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Bay, trip<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Damage reduction 10/silver, darkvision 60 ft., flight, scent<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +5, Ref +5, Will +5<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 17, Dex 15, Con 15, Int 6, Wis 14, Cha 10<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Listen +11, Spot +11, Search +7, Survival +11 (+13 following tracks)*<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Improved Initiative, Track<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>An evil-aligned plane<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary, pair, or pack (6-11)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>None<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Always neutral evil<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>4-6 HD (Medium); 7-9 HD (Large)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>+3 (cohort)<br/></td>\n\n</tr>\n</table><p>A yeth hound stands 5 feet tall at the shoulder and weighs about 400 pounds.</p><p>Yeth hounds cannot speak, but understand Infernal.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>Yeth hounds hunt only at night. They fear the sun and never venture out in daylight, even if their lives depend on it.</p><p>A yeth hound\'s natural weapons, as well as any weapons it wields, are treated as evil-aligned for the purpose of overcoming damage reduction.</p><div topic=\"Bay\" level=\"8\"><p><b>Bay (Su):</b> When a yeth hound howls or barks, all creatures except other evil outsiders within a 300-foot spread must succeed on a DC 11 Will save or become panicked for 2d4 rounds. This is a sonic mind-affecting fear effect. Whether or not the save is successful, an affected creature is immune to the same hound\'s bay for 24 hours. The save DC is Charisma-based.</p>\n</div><div topic=\"Trip\" level=\"8\"><p><b>Trip (Ex):</b> A yeth hound that hits with its bite attack can attempt to trip the opponent (+3 check modifier) as a free action without making a touch attack or provoking an attack of opportunity. If the attempt fails, the opponent cannot react to trip the yeth hound.</p>\n</div><div topic=\"Flight\" level=\"8\"><p><b>Flight (Su):</b> A yeth hound can cease or resume flight as a free action.</p>\n</div><div topic=\"Skills\" level=\"8\"><p><b>Skills:</b> *A yeth hound has a +4 racial bonus on Survival checks when tracking by scent.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 MonstersT-Z');
INSERT INTO monster VALUES (608,'Yrthak','Yrthak',NULL,'Huge','Magical Beast',NULL,'12d10+36 (102 hp)','+6','20 ft. (4 squares), fly 60 ft. (average)','18 (-2 size, +2 Dex, +8 natural), touch 10, flat-footed 16','+12','+25','Bite +15 melee (2d8+5) or sonic lance +12 ranged touch (6d6)','Bite +15 melee (2d8+5) and 2 claws +13 melee (1d6+2); or sonic lance +12 ranged touch (6d6)','15 ft.','10 ft.','Sonic lance, explosion','Blindsight 120 ft., immunities, vulnerability to sonic','Fort +11, Ref +10, Will +5','Str 20, Dex 14, Con 17, Int 7, Wis 13, Cha 11','Listen +12, Move Silently +10',NULL,'Endurance, Flyby Attack, Improved Initiative, Multiattack, Snatch',NULL,'Temperate mountains','Solitary or clutch (2-4)','9','None','Often neutral','13-16 HD (Huge); 17-36 HD (Gargantuan)','-','Blindsight (Ex), Explosion (Su), Sonic Lance (Su)','Yrthak; CR 9; Huge magical beast; HD 12d10+36; hp 102; Init +6; Spd 20 ft. (4 squares), fly 60 ft. (average); AC 18 (-2 size, +2 dex, +8 natural), touch 10, flat-footed 16; Base Atk +12; Grp +25; Atk +15 melee (2d8+5, bite) or +12 ranged touch (6d6, sonic lance); Full Atk +15 melee (2d8+5, bite) and +13 melee (1d6+2, 2 claws) or +12 ranged touch (6d6, sonic lance); Space/Reach 15 ft./10 ft.; SA Sonic lance, explosion; SQ Blindsight 120 ft., immunities, vulnerability to sonic; AL N; SV Fort +11, Ref +10, Will +5; Str 20, Dex 14, Con 17, Int 7, Wis 13, Cha 11\n\nSkills and Feats: Listen +12, Move Silently +10; Endurance, Flyby Attack, Improved Initiative, Multiattack, Snatch','\n      <div topic=\"Yrthak\" level=\"2\"><p><h2>Yrthak</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Yrthak</b><br/></td>\n\n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Huge Magical Beast<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>12d10+36 (102 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>20 ft. (4 squares), fly 60 ft. (average)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>18 (-2 size, +2 Dex, +8 natural), touch 10, flat-footed 16<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+12/+25<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Bite +15 melee (2d8+5) or sonic lance +12 ranged touch (6d6)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Bite +15 melee (2d8+5) and 2 claws +13 melee (1d6+2); or sonic lance +12 ranged touch (6d6)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>15 ft./10 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Sonic lance, explosion<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Blindsight 120 ft., immunities, vulnerability to sonic<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +11, Ref +10, Will +5<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 20, Dex 14, Con 17, Int 7, Wis 13, Cha 11<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Listen +12, Move Silently +10<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Endurance, Flyby Attack, Improved Initiative, Multiattack, Snatch<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Temperate mountains<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary or clutch (2-4)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>9<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>None<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Often neutral<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>13-16 HD (Huge); 17-36 HD (Gargantuan)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n</table><p>A yrthak is blind. It senses sound and movement by means of a special organ on its long tongue. It emits powerfully focused beams of sound from the protrusion on its head. The creature is a yellowish-green color, with the wings and fin being more yellow and the head and body more green. The teeth are yellow.</p><p>A yrthak is about 20 feet long, with a wingspan of 40 feet. It weighs about 5,000 pounds.</p><p>Despite their intelligence, yrthaks do not speak.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>A yrthak prefers to attack from the air, strafing the ground with sonic attacks or snatching up and dropping prey.</p><div topic=\"Sonic Lance\" level=\"8\"><p><b>Sonic Lance (Su):</b> Once every 2 rounds, a yrthak can focus sonic energy in a ray up to 60 feet long. This is a ranged touch attack that deals 6d6 points of damage to a single target.</p>\n</div><div topic=\"Explosion\" level=\"8\"><p><b>Explosion (Su):</b> A yrthak can fire its sonic lance at the ground, a large rock, a stone wall, or the like to create an explosion of shattered stone. This attack deals 2d6 points of piercing damage to all within 10 feet of the effect\'s center. This counts as a use of the sonic lance attack and thus is usable only once every 2 rounds, and never on the round following a sonic lance attack.</p>\n</div><div topic=\"Blindsight\" level=\"8\"><p><b>Blindsight (Ex):</b> A yrthak can ascertain all foes within 120 feet. Beyond that range it is considered blinded. Yrthaks are invulnerable to gaze attacks, visual effects of spells such as illusions, and other attack forms that rely on sight. A yrthak whose sense of hearing is impaired is effectively blinded, treating all targets as having total concealment.</p>\n</div><div topic=\"Immunities\" level=\"8\"><p><b>Immunities:</b> Yrthaks have immunity to gaze attacks, visual effects, illusions, and other attack forms that rely on sight.</p>\n</div><div topic=\"Skills\" level=\"8\"><p><b>Skills:</b> Yrthaks have a +4 racial bonus on Listen checks.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 MonstersT-Z');
INSERT INTO monster VALUES (609,'Zombie','Kobold Zombie',NULL,'Small','Undead',NULL,'2d12+3 (16 hp)','+0','30 ft. (6 squares; can\'t run)','13 (+1 size, +2 natural), touch 11, flat-footed 13','+1','-4','Spear+1 melee (1d6-1/x3) or slam +1 melee (1d4-1) or light crossbow +2 ranged (1d6/19-20)','Spear +0 melee (1d6-1/x3) or slam +0 melee (1d4-1) or light crossbow +1 ranged (1d6/19-20)','5 ft.','5 ft.','-','Single actions only, damage reduction 5/slashing, darkvision 60 ft., undead traits','Fort +0, Ref +0, Will +3','Str 8, Dex 11, Con -, Int -, Wis 10, Cha 1','-',NULL,'Toughness',NULL,'Temperate forests','Any','1/2','None','Always neutral evil','None','-','','Kobold zombie; CR 1/2; Small undead; HD 2d12+3; hp 16; Init +0; Spd 30 ft. (6 squares; can\'t run); AC 13 (+1 size, +2 natural), touch 11, flat-footed 13; Base Atk +1; Grp -4; Atk +1 melee (1d6-1/x3, spear) or +1 melee (1d4-1, slam) or +2 ranged (1d6/19-20, light crossbow); Full Atk +0 melee (1d6-1/x3, spear) or +0 melee (1d4-1, slam) or +1 ranged (1d6/19-20, light crossbow); Space/Reach 5 ft./5 ft.; SA -; SQ Single actions only, damage reduction 5/slashing, darkvision 60 ft., undead traits; AL NE; SV Fort +0, Ref +0, Will +3; Str 8, Dex 11, Con -, Int -, Wis 10, Cha 1\n\nSkills and Feats: -; Toughness','\n      <div topic=\"Creating A Zombie\" level=\"3\"><p><h3>Creating A Zombie</h3></p><p>\'Zombie\' is an acquired template that can be added to any corporeal creature (other than an undead) that has a skeletal system (referred to hereafter as the base creature).</p><div topic=\"Size and Type\" level=\"8\"><p><b>Size and Type:</b> The creature\'s type changes to undead. It retains any subtypes except alignment subtypes and subtypes that indicate kind. It does not gain the augmented subtype. It uses all the base creature\'s statistics and special abilities except as noted here.</p>\n</div><div topic=\"Hit Dice\" level=\"8\"><p><b>Hit Dice:</b> Drop any Hit Dice from class levels (to a minimum of 1), double the number of Hit Dice left, and raise them to d12s. If the base creature has more than 10 Hit Dice (not counting those gained with experience), it can\'t be made into a zombie with the <i>animate dead</i> spell.</p>\n</div><div topic=\"Speed\" level=\"8\"><p><b>Speed:</b> If the base creature can fly, its maneuverability rating drops to clumsy.</p>\n</div><div topic=\"Armor Class\" level=\"8\"><p><b>Armor Class:</b> Natural armor bonus increases by a number based on the zombie\'s size:</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Tiny or smaller<br/></td> <td>+0<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Small<br/></td>\n<td>+1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Medium<br/></td>\n<td>+2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Large<br/></td>\n<td>+3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Huge<br/></td>\n<td>+4<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Gargantuan<br/></td>\n<td>+7<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Colossal<br/></td>\n<td>+11<br/></td>\n\n</tr>\n</table>\n</div><div topic=\"Base Attack\" level=\"8\"><p><b>Base Attack:</b> A zombie has a base attack bonus equal to 1/2 its Hit Dice.</p>\n</div><div topic=\"Attacks\" level=\"8\"><p><b>Attacks:</b> A zombie retains all the natural weapons, manufactured weapon attacks, and weapon proficiencies of the base creature. A zombie also gains a slam attack.</p>\n</div><div topic=\"Damage\" level=\"8\"><p><b>Damage:</b> Natural and manufactured weapons deal damage normally. A slam attack deals damage depending on the zombie\'s size. (Use the base creature\'s slam damage if it\'s better.)</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Fine<br/></td> <td>1<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Diminutive<br/></td>\n<td>1d2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Tiny<br/></td>\n<td>1d3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Small<br/></td>\n<td>1d4<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Medium<br/></td>\n<td>1d6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Large<br/></td>\n<td>1d8<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Huge<br/></td>\n<td>2d6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Gargantuan<br/></td>\n<td>2d8<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Colossal<br/></td>\n<td>4d6<br/></td>\n\n</tr>\n</table>\n</div><div topic=\"Special Attacks\" level=\"8\"><p><b>Special Attacks:</b> A zombie retains none of the base creature\'s special attacks.</p>\n</div><div topic=\"Special Qualities\" level=\"8\"><p><b>Special Qualities:</b> A zombie loses most special qualities of the base creature. It retains any extraordinary special qualities that improve its melee or ranged attacks. A zombie gains the following special quality.</p><p><i>Single Actions Only (Ex):</i> Zombies have poor reflexes and can perform only a single move action or attack action each round. A zombie can move up to its speed and attack in the same round, but only if it attempts a charge.</p>\n</div><div topic=\"Saves\" level=\"8\"><p><b>Saves:</b> Base save bonuses are Fort +1/3 HD, Ref +1/3 HD, and Will +1/2 HD + 2.</p>\n</div><div topic=\"Abilities\" level=\"8\"><p><b>Abilities:</b> A zombie\'s Strength increases by +2, its Dexterity decreases by 2, it has no Constitution or Intelligence score, its Wisdom changes to 10, and its Charisma changes to 1.</p>\n</div><div topic=\"Skills\" level=\"8\"><p><b>Skills:</b> A zombie has no skills.</p>\n</div><div topic=\"Feats\" level=\"8\"><p><b>Feats:</b> A zombie loses all feats of the base creature and gains Toughness.</p>\n</div><div topic=\"Environment\" level=\"8\"><p><b>Environment:</b> Any land and underground.</p>\n</div><div topic=\"Organization\" level=\"8\"><p><b>Organization:</b> Any.</p>\n</div><div topic=\"Challenge Rating\" level=\"8\"><p><b>Challenge Rating:</b> Depends on Hit Dice, as follows:</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice</b><br/></td>\n<td><b>Challenge Rating</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>1/2<br/></td>\n<td>1/8<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>1<br/></td>\n<td>1/4<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>2<br/></td>\n<td>1/2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>4<br/></td>\n<td>1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>6<br/></td>\n<td>2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>8-10<br/></td>\n<td>3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>12-14<br/></td>\n<td>4<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>15-16<br/></td>\n<td>5<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>18-20<br/></td>\n<td>6<br/></td>\n\n</tr>\n</table>\n</div><div topic=\"Treasure\" level=\"8\"><p><b>Treasure:</b> None.</p>\n</div><div topic=\"Alignment\" level=\"8\"><p><b>Alignment:</b> Always neutral evil.</p><p>Advancement: As base creature, but double Hit Dice (maximum 20), or - if the base creature advances by character class.</p>\n</div><div topic=\"Level Adjustment\" level=\"8\"><p><b>Level Adjustment:</b> -.</p><p/><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Kobold Zombie</b><br/></td>\n\n\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Small Undead<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>2d12+3 (16 hp)<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+0<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>30 ft. (6 squares; can\'t run)<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>13 (+1 size, +2 natural), touch 11, flat-footed 13<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+1/-4<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Spear+1 melee (1d6-1/x3) or slam +1 melee (1d4-1) or light crossbow +2 ranged (1d6/19-20)<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Spear +0 melee (1d6-1/x3) or slam +0 melee (1d4-1) or light crossbow +1 ranged (1d6/19-20)<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>5 ft./5 ft.<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>-<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Single actions only, damage reduction 5/slashing, darkvision 60 ft., undead traits<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +0, Ref +0, Will +3<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 8, Dex 11, Con -, Int -, Wis 10, Cha 1<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>-<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Toughness<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Temperate forests<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Any<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>1/2<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>None<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Always neutral evil<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>None<br/></td>\n\n\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n\n\n</tr>\n</table><p/><p/><p/><p/>\n</div>\n</div>\n    ','SRD 3.5 MonstersT-Z');
INSERT INTO monster VALUES (610,'Zombie','Human Commoner Zombie',NULL,'Medium','Undead',NULL,'2d12+3 (16 hp)','-1','30 ft. (6 squares; can\'t run)','11 (-1 Dex, +2 natural), touch 9, flat-footed 11','+1','+2','Slam+2 melee (1d6+1) or club +2 melee (1d6+1)','Slam+2 melee, (1d6+1) or club +2 melee (1d6+1)','5 ft.','5 ft','-','Single actions only, damage reduction 5/slashing, darkvision 60 ft., undead traits','Fort +0, Ref -1, Will +3','Str 12, Dex 8, Con -, Int -, Wis 10, Cha 1','-',NULL,'Toughness',NULL,'Any','Any','1/2','None','Always neutral evil','None','-','','Human commoner zombie; CR 1/2; Medium undead; HD 2d12+3; hp 16; Init -1; Spd 30 ft. (6 squares; can\'t run); AC 11 (-1 dex, +2 natural), touch 9, flat-footed 11; Base Atk +1; Grp +2; Atk +2 melee (1d6+1, slam) or +2 melee (1d6+1, club); Full Atk +2 melee (slam) and (1d6+1) or +2 melee (1d6+1, club); Space/Reach 5 ft./5 ft; SA -; SQ Single actions only, damage reduction 5/slashing, darkvision 60 ft., undead traits; AL NE; SV Fort +0, Ref -1, Will +3; Str 12, Dex 8, Con -, Int -, Wis 10, Cha 1\n\nSkills and Feats: -; Toughness','\n      <div topic=\"Creating A Zombie\" level=\"3\"><p><h3>Creating A Zombie</h3></p><p>\'Zombie\' is an acquired template that can be added to any corporeal creature (other than an undead) that has a skeletal system (referred to hereafter as the base creature).</p><div topic=\"Size and Type\" level=\"8\"><p><b>Size and Type:</b> The creature\'s type changes to undead. It retains any subtypes except alignment subtypes and subtypes that indicate kind. It does not gain the augmented subtype. It uses all the base creature\'s statistics and special abilities except as noted here.</p>\n</div><div topic=\"Hit Dice\" level=\"8\"><p><b>Hit Dice:</b> Drop any Hit Dice from class levels (to a minimum of 1), double the number of Hit Dice left, and raise them to d12s. If the base creature has more than 10 Hit Dice (not counting those gained with experience), it can\'t be made into a zombie with the <i>animate dead</i> spell.</p>\n</div><div topic=\"Speed\" level=\"8\"><p><b>Speed:</b> If the base creature can fly, its maneuverability rating drops to clumsy.</p>\n</div><div topic=\"Armor Class\" level=\"8\"><p><b>Armor Class:</b> Natural armor bonus increases by a number based on the zombie\'s size:</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Tiny or smaller<br/></td> <td>+0<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Small<br/></td>\n<td>+1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Medium<br/></td>\n<td>+2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Large<br/></td>\n<td>+3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Huge<br/></td>\n<td>+4<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Gargantuan<br/></td>\n<td>+7<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Colossal<br/></td>\n<td>+11<br/></td>\n\n</tr>\n</table>\n</div><div topic=\"Base Attack\" level=\"8\"><p><b>Base Attack:</b> A zombie has a base attack bonus equal to 1/2 its Hit Dice.</p>\n</div><div topic=\"Attacks\" level=\"8\"><p><b>Attacks:</b> A zombie retains all the natural weapons, manufactured weapon attacks, and weapon proficiencies of the base creature. A zombie also gains a slam attack.</p>\n</div><div topic=\"Damage\" level=\"8\"><p><b>Damage:</b> Natural and manufactured weapons deal damage normally. A slam attack deals damage depending on the zombie\'s size. (Use the base creature\'s slam damage if it\'s better.)</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Fine<br/></td> <td>1<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Diminutive<br/></td>\n<td>1d2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Tiny<br/></td>\n<td>1d3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Small<br/></td>\n<td>1d4<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Medium<br/></td>\n<td>1d6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Large<br/></td>\n<td>1d8<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Huge<br/></td>\n<td>2d6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Gargantuan<br/></td>\n<td>2d8<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Colossal<br/></td>\n<td>4d6<br/></td>\n\n</tr>\n</table>\n</div><div topic=\"Special Attacks\" level=\"8\"><p><b>Special Attacks:</b> A zombie retains none of the base creature\'s special attacks.</p>\n</div><div topic=\"Special Qualities\" level=\"8\"><p><b>Special Qualities:</b> A zombie loses most special qualities of the base creature. It retains any extraordinary special qualities that improve its melee or ranged attacks. A zombie gains the following special quality.</p><p><i>Single Actions Only (Ex):</i> Zombies have poor reflexes and can perform only a single move action or attack action each round. A zombie can move up to its speed and attack in the same round, but only if it attempts a charge.</p>\n</div><div topic=\"Saves\" level=\"8\"><p><b>Saves:</b> Base save bonuses are Fort +1/3 HD, Ref +1/3 HD, and Will +1/2 HD + 2.</p>\n</div><div topic=\"Abilities\" level=\"8\"><p><b>Abilities:</b> A zombie\'s Strength increases by +2, its Dexterity decreases by 2, it has no Constitution or Intelligence score, its Wisdom changes to 10, and its Charisma changes to 1.</p>\n</div><div topic=\"Skills\" level=\"8\"><p><b>Skills:</b> A zombie has no skills.</p>\n</div><div topic=\"Feats\" level=\"8\"><p><b>Feats:</b> A zombie loses all feats of the base creature and gains Toughness.</p>\n</div><div topic=\"Environment\" level=\"8\"><p><b>Environment:</b> Any land and underground.</p>\n</div><div topic=\"Organization\" level=\"8\"><p><b>Organization:</b> Any.</p>\n</div><div topic=\"Challenge Rating\" level=\"8\"><p><b>Challenge Rating:</b> Depends on Hit Dice, as follows:</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice</b><br/></td>\n<td><b>Challenge Rating</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>1/2<br/></td>\n<td>1/8<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>1<br/></td>\n<td>1/4<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>2<br/></td>\n<td>1/2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>4<br/></td>\n<td>1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>6<br/></td>\n<td>2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>8-10<br/></td>\n<td>3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>12-14<br/></td>\n<td>4<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>15-16<br/></td>\n<td>5<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>18-20<br/></td>\n<td>6<br/></td>\n\n</tr>\n</table>\n</div><div topic=\"Treasure\" level=\"8\"><p><b>Treasure:</b> None.</p>\n</div><div topic=\"Alignment\" level=\"8\"><p><b>Alignment:</b> Always neutral evil.</p><p>Advancement: As base creature, but double Hit Dice (maximum 20), or - if the base creature advances by character class.</p>\n</div><div topic=\"Level Adjustment\" level=\"8\"><p><b>Level Adjustment:</b> -.</p><p/><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n\n<td><b>Human Commoner Zombie</b><br/></td>\n\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n\n<td>Medium Undead<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n\n<td>2d12+3 (16 hp)<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n\n<td>-1<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n\n<td>30 ft. (6 squares; can\'t run)<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n\n<td>11 (-1 Dex, +2 natural), touch 9, flat-footed 11<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n\n<td>+1/+2<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n\n<td>Slam+2 melee (1d6+1) or club +2 melee (1d6+1)<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n\n<td>Slam+2 melee, (1d6+1) or club +2 melee (1d6+1)<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n\n<td>5 ft./5 ft<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n\n<td>-<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n\n<td>Single actions only, damage reduction 5/slashing, darkvision 60 ft., undead traits<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n\n<td>Fort +0, Ref -1, Will +3<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n\n<td>Str 12, Dex 8, Con -, Int -, Wis 10, Cha 1<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n\n<td>-<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n\n<td>Toughness<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n\n<td>Any<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n\n<td>Any<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n\n<td>1/2<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n\n<td>None<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n\n<td>Always neutral evil<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n\n<td>None<br/></td>\n\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n\n<td>-<br/></td>\n\n\n</tr>\n</table><p/><p/><p/><p/>\n</div>\n</div>\n    ','SRD 3.5 MonstersT-Z');
INSERT INTO monster VALUES (611,'Zombie','Troglodyte Zombie',NULL,'Medium','Undead',NULL,'4d12+3 (29 hp)','-2','30 ft. (6 squares; can\'t run)','16 (-2 Dex, +8 natural), touch 8, flat-footed 16','+2','+3','Greatclub +3 melee (1d10+1) or bite +3 melee (1d4+1) or slam +3 melee (1d6+1) or javelin +0 ranged (1d6+1)','Greatclub +3 melee (1d10+1) or bite +3 melee (1d4+1) or slam +3 melee (1d6+1) or javelin +0 ranged (1d6+1)','5 ft.','5 ft','-','Single actions only, damage reduction 5/slashing, darkvision 60 ft., undead traits','Fort +1, Ref -1, Will +4','Str 12, Dex 7, Con -, Int -, Wis 10, Cha 1','-',NULL,'Toughness',NULL,'Underground','Any','1','None','Always neutral evil','None','-','','Troglodyte zombie; CR 1; Medium undead; HD 4d12+3; hp 29; Init -2; Spd 30 ft. (6 squares; can\'t run); AC 16 (-2 dex, +8 natural), touch 8, flat-footed 16; Base Atk +2; Grp +3; Atk +3 melee (1d10+1, greatclub) or +3 melee (1d4+1, bite) or +3 melee (1d6+1, slam) or +0 ranged (1d6+1, javelin); Full Atk +3 melee (1d10+1, greatclub) or +3 melee (1d4+1, bite) or +3 melee (1d6+1, slam) or +0 ranged (1d6+1, javelin); Space/Reach 5 ft./5 ft; SA -; SQ Single actions only, damage reduction 5/slashing, darkvision 60 ft., undead traits; AL NE; SV Fort +1, Ref -1, Will +4; Str 12, Dex 7, Con -, Int -, Wis 10, Cha 1\n\nSkills and Feats: -; Toughness','\n      <div topic=\"Creating A Zombie\" level=\"3\"><p><h3>Creating A Zombie</h3></p><p>\'Zombie\' is an acquired template that can be added to any corporeal creature (other than an undead) that has a skeletal system (referred to hereafter as the base creature).</p><div topic=\"Size and Type\" level=\"8\"><p><b>Size and Type:</b> The creature\'s type changes to undead. It retains any subtypes except alignment subtypes and subtypes that indicate kind. It does not gain the augmented subtype. It uses all the base creature\'s statistics and special abilities except as noted here.</p>\n</div><div topic=\"Hit Dice\" level=\"8\"><p><b>Hit Dice:</b> Drop any Hit Dice from class levels (to a minimum of 1), double the number of Hit Dice left, and raise them to d12s. If the base creature has more than 10 Hit Dice (not counting those gained with experience), it can\'t be made into a zombie with the <i>animate dead</i> spell.</p>\n</div><div topic=\"Speed\" level=\"8\"><p><b>Speed:</b> If the base creature can fly, its maneuverability rating drops to clumsy.</p>\n</div><div topic=\"Armor Class\" level=\"8\"><p><b>Armor Class:</b> Natural armor bonus increases by a number based on the zombie\'s size:</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Tiny or smaller<br/></td> <td>+0<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Small<br/></td>\n<td>+1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Medium<br/></td>\n<td>+2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Large<br/></td>\n<td>+3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Huge<br/></td>\n<td>+4<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Gargantuan<br/></td>\n<td>+7<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Colossal<br/></td>\n<td>+11<br/></td>\n\n</tr>\n</table>\n</div><div topic=\"Base Attack\" level=\"8\"><p><b>Base Attack:</b> A zombie has a base attack bonus equal to 1/2 its Hit Dice.</p>\n</div><div topic=\"Attacks\" level=\"8\"><p><b>Attacks:</b> A zombie retains all the natural weapons, manufactured weapon attacks, and weapon proficiencies of the base creature. A zombie also gains a slam attack.</p>\n</div><div topic=\"Damage\" level=\"8\"><p><b>Damage:</b> Natural and manufactured weapons deal damage normally. A slam attack deals damage depending on the zombie\'s size. (Use the base creature\'s slam damage if it\'s better.)</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Fine<br/></td> <td>1<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Diminutive<br/></td>\n<td>1d2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Tiny<br/></td>\n<td>1d3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Small<br/></td>\n<td>1d4<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Medium<br/></td>\n<td>1d6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Large<br/></td>\n<td>1d8<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Huge<br/></td>\n<td>2d6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Gargantuan<br/></td>\n<td>2d8<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Colossal<br/></td>\n<td>4d6<br/></td>\n\n</tr>\n</table>\n</div><div topic=\"Special Attacks\" level=\"8\"><p><b>Special Attacks:</b> A zombie retains none of the base creature\'s special attacks.</p>\n</div><div topic=\"Special Qualities\" level=\"8\"><p><b>Special Qualities:</b> A zombie loses most special qualities of the base creature. It retains any extraordinary special qualities that improve its melee or ranged attacks. A zombie gains the following special quality.</p><p><i>Single Actions Only (Ex):</i> Zombies have poor reflexes and can perform only a single move action or attack action each round. A zombie can move up to its speed and attack in the same round, but only if it attempts a charge.</p>\n</div><div topic=\"Saves\" level=\"8\"><p><b>Saves:</b> Base save bonuses are Fort +1/3 HD, Ref +1/3 HD, and Will +1/2 HD + 2.</p>\n</div><div topic=\"Abilities\" level=\"8\"><p><b>Abilities:</b> A zombie\'s Strength increases by +2, its Dexterity decreases by 2, it has no Constitution or Intelligence score, its Wisdom changes to 10, and its Charisma changes to 1.</p>\n</div><div topic=\"Skills\" level=\"8\"><p><b>Skills:</b> A zombie has no skills.</p>\n</div><div topic=\"Feats\" level=\"8\"><p><b>Feats:</b> A zombie loses all feats of the base creature and gains Toughness.</p>\n</div><div topic=\"Environment\" level=\"8\"><p><b>Environment:</b> Any land and underground.</p>\n</div><div topic=\"Organization\" level=\"8\"><p><b>Organization:</b> Any.</p>\n</div><div topic=\"Challenge Rating\" level=\"8\"><p><b>Challenge Rating:</b> Depends on Hit Dice, as follows:</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice</b><br/></td>\n<td><b>Challenge Rating</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>1/2<br/></td>\n<td>1/8<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>1<br/></td>\n<td>1/4<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>2<br/></td>\n<td>1/2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>4<br/></td>\n<td>1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>6<br/></td>\n<td>2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>8-10<br/></td>\n<td>3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>12-14<br/></td>\n<td>4<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>15-16<br/></td>\n<td>5<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>18-20<br/></td>\n<td>6<br/></td>\n\n</tr>\n</table>\n</div><div topic=\"Treasure\" level=\"8\"><p><b>Treasure:</b> None.</p>\n</div><div topic=\"Alignment\" level=\"8\"><p><b>Alignment:</b> Always neutral evil.</p><p>Advancement: As base creature, but double Hit Dice (maximum 20), or - if the base creature advances by character class.</p>\n</div><div topic=\"Level Adjustment\" level=\"8\"><p><b>Level Adjustment:</b> -.</p><p/><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n\n\n<td><b>Troglodyte Zombie</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n\n\n<td>Medium Undead<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n\n\n<td>4d12+3 (29 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n\n\n<td>-2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n\n\n<td>30 ft. (6 squares; can\'t run)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n\n\n<td>16 (-2 Dex, +8 natural), touch 8, flat-footed 16<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n\n\n<td>+2/+3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n\n\n<td>Greatclub +3 melee (1d10+1) or bite +3 melee (1d4+1) or slam +3 melee (1d6+1) or javelin +0 ranged (1d6+1)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n\n\n<td>Greatclub +3 melee (1d10+1) or bite +3 melee (1d4+1) or slam +3 melee (1d6+1) or javelin +0 ranged (1d6+1)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n\n\n<td>5 ft./5 ft<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n\n\n<td>-<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n\n\n<td>Single actions only, damage reduction 5/slashing, darkvision 60 ft., undead traits<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n\n\n<td>Fort +1, Ref -1, Will +4<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n\n\n<td>Str 12, Dex 7, Con -, Int -, Wis 10, Cha 1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n\n\n<td>-<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n\n\n<td>Toughness<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n\n\n<td>Underground<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n\n\n<td>Any<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n\n\n<td>1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n\n\n<td>None<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n\n\n<td>Always neutral evil<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n\n\n<td>None<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n\n\n<td>-<br/></td>\n\n</tr>\n</table><p/><p/><p/><p/>\n</div>\n</div>\n    ','SRD 3.5 MonstersT-Z');
